/// True when tile `a` merges with tile `b` for autotiling purposes.
#[inline]
pub fn merges(a: u16, b: u16) -> bool {
    let (a, b) = (a as usize, b as usize);
    if a >= TILE_COUNT || b >= TILE_COUNT {
        return false;
    }
    (MERGE[a * 12 + (b >> 6)] >> (b & 63)) & 1 != 0
}
